_EMBEDDED = {
    "team": (_B0, True),
    "team.autopilot": (_B1, True),
    "team.detector": (_B2, True),
    "team.teacher": (_B3, True),
    "team.autopilot.agent": (_B4, False),
    "team.autopilot.freedir": (_B5, False),
    "team.detector.geom": (_B6, False),
    "team.detector.localize": (_B7, False),
    "team.detector.padnet": (_B8, False),
    "team.detector.pads": (_B9, False),
    "team.teacher.geometry": (_B10, False),
}


class _EmbeddedLoader(_iabc.InspectLoader):
    """Serve an embedded module's source to the normal import machinery.

    InspectLoader gives us exec_module and module_from_spec for free, so the
    modules get real `__spec__`/`__package__` values and relative imports inside
    the package resolve exactly as they do on disk.
    """

    def get_source(self, fullname):
        return _b64.b64decode(_EMBEDDED[fullname][0]).decode("utf-8")

    def is_package(self, fullname):
        return _EMBEDDED[fullname][1]

    def get_filename(self, fullname):
        # Point at this generated file so any Path(__file__) lookup inside the
        # package resolves against the unpacked bundle root.
        return __file__


class _EmbeddedFinder(_iabc.MetaPathFinder):
    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _EMBEDDED:
            return None
        loader = _EmbeddedLoader()
        spec = _iutil.spec_from_loader(
            fullname, loader, is_package=_EMBEDDED[fullname][1])
        if _EMBEDDED[fullname][1]:
            # A package with no real directory: empty search path, so submodules
            # are found only through this finder and never half-resolved from an
            # unrelated `team/` that happens to be on sys.path.
            spec.submodule_search_locations = []
        return spec


# Ahead of the path finders: a stale `team/` in the working directory must not
# shadow the version this zip was built and benchmarked from.
if not any(isinstance(_f, _EmbeddedFinder) for _f in _sys.meta_path):
    _sys.meta_path.insert(0, _EmbeddedFinder())

"""DroneFlightController — the V5.1 submission entry point for cf_swarm_autopilot.

The validator constructs this once, calls `reset()` per episode and `act(obs)` per
step, and hands `act` nothing but the observation: `depth` (N,128,128,1) and
`state` (N,190). No task metadata, no simulator, no ground truth. This family has
no RGB.

Behind it is exactly the code the benchmark scores:

    PadNetDetector       the depth segmenter, batched over the whole fleet
    SwarmAutopilotAgent  classify the map from the start pads, sweep the clue on
                         disjoint angular lanes, claim a corroborated pad, land

TWO checkpoints ship: a general model and a forest specialist, routed by the
agent's own forest test. Together they are 3.4 MB against a 50 MB uncompressed
cap (swarm/core/submission_policy.py), so carrying both costs nothing.

Budget: `act()` has RPC_STEP_TIMEOUT_SEC = 0.500 (2 s on the first call). The
detector runs every `detect_every` steps rather than every step and batches all N
drones into one forward pass. Timed by team/scripts/time_act.py — run it after
any change to the detector or the config, because a timeout scores nothing at
all, not a worse number.
"""

import os
import sys
from pathlib import Path

import numpy as np

_HERE = Path(__file__).resolve().parent
for _p in (_HERE, _HERE.parent, _HERE.parent.parent):
    if str(_p) not in sys.path:
        sys.path.insert(0, str(_p))

from team.autopilot.agent import AutopilotConfig, SwarmAutopilotAgent  # noqa: E402
from team.detector.pads import PadConfig                               # noqa: E402

# THE CONFIG WE SHIP. It must match what the benchmarks measure, and it does NOT
# come for free: `free_dir` defaults to False in the dataclass and is switched on
# by bench_autopilot's --free-dir flag, which every panel since v22 passes. An
# artifact built without it would run the pre-v22 obstacle picker -- the +0.15
# change, our single biggest win -- and score ~0.22 instead of ~0.375, while
# passing admission, the loader check and the timing check, because the agent
# loads and flies perfectly well. It is just the wrong agent.
#
# Anything the benchmark passes on the command line has to appear here.
#
# ELE tilt hardening (vs King): reactive only — no climb_clear / post_climb tax.
# Restored to the 20260805_035855 batch config (open mean 0.596, city 0.501):
# climb_creep_tilt + XY fade + short tilt_guard; King-speed climb/search.
SHIPPED_CFG = dict(
    creep_speed=0.48,
    descend_speed=0.48,
    flare_alt=0.15,
    free_dir=True,
    forest_speed=2.8,
    climb_clear_m=0.0,
    climb_creep_tilt=0.28,
    tilt_fade_lo=0.4,
    tilt_fade_hi=0.7,
    tilt_guard_rad=0.62,
    tilt_guard_brake=1.5,
    tilt_guard_hold_sec=0.55,
    tilt_guard_speed_cap=1.8,
    climb_max_delta_v=0.0,
    post_climb_soft_sec=0.0,
    post_climb_speed_frac=1.0,
    own_annulus=True,
    own_arc_m=100.0,
    own_step_m=12.0,
    mountain_avoid_climb=2.5,
    own_maps=('city',),
    own_monotone_maps=('city',),
    own_near_first=(),
    own_split_tall=0.28,
    own_split_kind='',
    commit_t=50.0,
    landed_done=True,
    investigate=True,
    forest_sink_speed=2.0,
    descend_enter_r=1.5,
    descend_enter_wide=('forest',),
    investigate_hits=1,
    investigate_skip=('village', 'mountain'),
    descend_commit=True,
    avoid_range_mtn=20.0,
    yaw_scan_deg=50.0,
    mountain_min_hits=3,
    yaw_scan_maps=('mountain', 'city'),
)

WEIGHTS = {
    # Two spellings each: the training script writes <run>/best.pt, but a checkpoint
    # copied back off the server sometimes lands as a bare file named after the run.
    # _find() requires is_file(), so a run directory listed first is skipped rather
    # than resolved to a 0-byte entry -- but keep the real file first regardless.
    # padnet6_sb is the size-balanced general net; it replaced padnet5 at v28.
    "general": ("team/out/padnet6_sb/best.pt", "team/out/padnet6_sb"),
    "forest": ("team/out/padforest_net/best.pt", "team/out/padforest_net"),
    # Village specialist: +0.10 closed-loop on the v2 base, three-band replicated.
    "village": ("team/out/padvillage_net/best.pt", "team/out/padvillage_net"),
    # No mountain-specific file: mountain routes to the VILLAGE weights, which
    # beat the general head there by 0.632 -> 0.840 recall on held-out frames.
    # A dedicated head may still beat both; this costs zero extra bytes.
}
ACTION_DIM = 5


def _find(rels):
    """Resolve a weight path inside the bundle, wherever it got unpacked.

    The zip root, this directory and the repo root are all plausible working
    directories depending on how the runner unpacks us, and the bare filename is
    the fallback for a flattened bundle.
    """
    if isinstance(rels, str):
        rels = (rels,)
    for base in (_HERE, _HERE.parent, _HERE.parent.parent, Path.cwd()):
        for rel in rels:
            for cand in (base / rel, base / Path(rel).name):
                if cand.exists() and cand.is_file():
                    return str(cand)
    return None


class DroneFlightController:
    def __init__(self):
        import torch

        # One thread: the validator runs several agents on one box and these
        # models are small enough that thread contention costs more than it buys.
        torch.set_num_threads(int(os.environ.get("SWARM_TORCH_THREADS", "1")))
        device = os.environ.get("SWARM_DEVICE", "cpu")

        from team.detector.pads import PadNetDetector

        # Resolved INDEPENDENTLY: nesting the forest lookup inside the general one
        # means a missing general weight silently costs us the forest model too.
        det = fdet = None
        gen = _find(WEIGHTS["general"])
        if gen is not None:
            det = PadNetDetector(gen, device=device)
        fp = _find(WEIGHTS["forest"])
        if fp is not None:
            # Stricter shape test where the branches are: measured 40% of forest
            # clutter removed for 11% of its pads.
            fdet = PadNetDetector(
                fp, device=device,
                cfg=PadConfig(net_max_aspect=1.6, net_min_short=0.45),
            )
        # detector=None falls back to the geometric proposer rather than failing:
        # a worse flight beats a dead one.
        vp = _find(WEIGHTS["village"])
        vdet = PadNetDetector(vp, device=device, thr=0.80) if vp is not None else None
        self._agent = SwarmAutopilotAgent(cfg=AutopilotConfig(**SHIPPED_CFG),
                                          detector=det, forest_detector=fdet,
                                          village_detector=vdet,
                                          # Same weights as the village head:
                                          # it resolves mountain pads at recall
                                          # 0.840 vs the general head's 0.632.
                                          # Inert unless mountain_detector_swap.
                                          mountain_detector=vdet)

    def reset(self) -> None:
        self._agent.reset()

    def act(self, observation) -> np.ndarray:
        state = np.asarray(observation["state"])
        n = int(state.shape[0]) if state.ndim == 2 else 1
        try:
            action = self._agent.act(observation)
            action = np.asarray(action, dtype=np.float32).reshape(n, ACTION_DIM)
            if not np.all(np.isfinite(action)):
                action = np.nan_to_num(action, nan=0.0, posinf=0.0, neginf=0.0)
            return np.clip(action, -1.0, 1.0)
        except Exception:  # noqa: BLE001
            # A raised exception is a dead episode; a hover is merely a bad one.
            return np.zeros((n, ACTION_DIM), dtype=np.float32)
